import React, { useState, useEffect } from 'react';
import { Layout, Trash2, Search, AppWindow, Calendar, ShieldCheck, Box, LayoutGrid, List } from 'lucide-react';
import { getAllFrontlineApps, deleteFrontlineApp } from '../utils/supabaseFrontlineDB';
import toast from 'react-hot-toast';

const AppManagement = () => {
    const [apps, setApps] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchTerm, setSearchTerm] = useState('');
    const [viewMode, setViewMode] = useState('grid'); // 'grid' | 'list'

    useEffect(() => {
        loadApps();
    }, []);

    const loadApps = async () => {
        setLoading(true);
        try {
            const data = await getAllFrontlineApps();
            setApps(data || []);
        } catch (error) {
            console.error('Failed to load apps:', error);
            toast.error('Failed to load applications.');
        } finally {
            setLoading(false);
        }
    };

    const handleUninstall = async (appId, appName) => {
        if (window.confirm(`Are you sure you want to uninstall and permanently delete "${appName}"? This will also delete any associated tables and data.`)) {
            const loadingToast = toast.loading('Uninstalling application...');
            try {
                await deleteFrontlineApp(appId);

                // If it was a template from AppStore, remove it from localStorage
                try {
                    const raw = localStorage.getItem('installedAppStoreTemplates');
                    if (raw) {
                        const installed = JSON.parse(raw);
                        const newInstalled = {};
                        let changed = false;
                        for (const [tplId, installedAppId] of Object.entries(installed)) {
                            if (installedAppId === appId) {
                                changed = true;
                            } else {
                                newInstalled[tplId] = installedAppId;
                            }
                        }
                        if (changed) {
                            localStorage.setItem('installedAppStoreTemplates', JSON.stringify(newInstalled));
                        }
                    }
                } catch (e) {
                    console.warn('Failed to clean up localStorage:', e);
                }

                toast.success('Application uninstalled successfully!', { id: loadingToast });
                loadApps();
            } catch (error) {
                console.error('Failed to uninstall app:', error);
                toast.error('Failed to uninstall application.', { id: loadingToast });
            }
        }
    };

    const getAppCategory = (app) => {
        if (!app.config) return 'Custom App';
        if (app.config.templateCategory) return app.config.templateCategory;
        if (app.description && app.description.includes('Template')) return 'Template App';
        return 'Custom App';
    };

    const filteredApps = apps.filter(app => 
        (app.name || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
        getAppCategory(app).toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div style={{ height: '100%', display: 'flex', flexDirection: 'column', backgroundColor: '#f8fafc' }}>
            <div style={{ padding: '24px 32px', borderBottom: '1px solid #e2e8f0', backgroundColor: 'white', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                    <h2 style={{ margin: 0, fontSize: '1.75rem', fontWeight: 900, color: '#0f172a', display: 'flex', alignItems: 'center', gap: '12px' }}>
                        <AppWindow size={28} color="#2563eb" />
                        App Management
                    </h2>
                    <p style={{ margin: '8px 0 0 0', color: '#64748b', fontSize: '0.95rem' }}>View and manage installed frontline applications</p>
                </div>
            </div>

            <div style={{ padding: '32px', flex: 1, overflowY: 'auto' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
                    <div style={{ position: 'relative', width: '100%', maxWidth: '500px' }}>
                        <Search style={{ position: 'absolute', left: '16px', top: '50%', transform: 'translateY(-50%)', color: '#94a3b8' }} size={18} />
                        <input
                            type="text"
                            placeholder="Search apps by name or category..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            style={{
                                width: '100%', padding: '14px 16px 14px 44px',
                                borderRadius: '12px', border: '1px solid #e2e8f0', backgroundColor: 'white',
                                fontSize: '0.95rem', color: '#1e293b', outline: 'none', boxShadow: '0 1px 2px rgba(0,0,0,0.05)'
                            }}
                        />
                    </div>
                    <div style={{ display: 'flex', backgroundColor: 'white', borderRadius: '8px', border: '1px solid #e2e8f0', padding: '4px' }}>
                        <button 
                            onClick={() => setViewMode('grid')}
                            style={{ padding: '8px', border: 'none', backgroundColor: viewMode === 'grid' ? '#f1f5f9' : 'transparent', borderRadius: '4px', cursor: 'pointer', color: viewMode === 'grid' ? '#0f172a' : '#94a3b8', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                            title="Grid View"
                        >
                            <LayoutGrid size={18} />
                        </button>
                        <button 
                            onClick={() => setViewMode('list')}
                            style={{ padding: '8px', border: 'none', backgroundColor: viewMode === 'list' ? '#f1f5f9' : 'transparent', borderRadius: '4px', cursor: 'pointer', color: viewMode === 'list' ? '#0f172a' : '#94a3b8', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                            title="List View"
                        >
                            <List size={18} />
                        </button>
                    </div>
                </div>

                {loading ? (
                    <div style={{ padding: '60px', textAlign: 'center', color: '#64748b' }}>Loading applications...</div>
                ) : filteredApps.length === 0 ? (
                    <div style={{ textAlign: 'center', padding: '60px', backgroundColor: 'white', borderRadius: '16px', border: '1px dashed #cbd5e1' }}>
                        <Box size={48} color="#cbd5e1" style={{ marginBottom: '16px' }} />
                        <h3 style={{ margin: 0, color: '#1e293b', fontSize: '1.25rem' }}>No apps found</h3>
                        <p style={{ color: '#64748b', margin: '8px 0 0 0' }}>Install applications from the App Store or build them in App Builder.</p>
                    </div>
                ) : viewMode === 'grid' ? (
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(400px, 1fr))', gap: '24px' }}>
                        {filteredApps.map(app => (
                            <div key={app.id} style={{ backgroundColor: 'white', borderRadius: '16px', border: '1px solid #e2e8f0', overflow: 'hidden', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.05)', display: 'flex', flexDirection: 'column' }}>
                                <div style={{ padding: '24px', display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', borderBottom: '1px solid #f1f5f9' }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
                                        <div style={{ width: '56px', height: '56px', borderRadius: '12px', backgroundColor: '#f0f7ff', border: '1px solid #bfdbfe', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#2563eb' }}>
                                            <Layout size={28} />
                                        </div>
                                        <div>
                                            <h3 style={{ margin: 0, fontSize: '1.15rem', fontWeight: 800, color: '#1e293b' }}>{app.name || 'Untitled App'}</h3>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginTop: '6px', color: '#64748b', fontSize: '0.8rem', fontWeight: 600 }}>
                                                <span style={{ padding: '4px 10px', borderRadius: '20px', backgroundColor: '#f8fafc', border: '1px solid #e2e8f0' }}>
                                                    {getAppCategory(app)}
                                                </span>
                                                {app.version && (
                                                    <span style={{ padding: '4px 8px', borderRadius: '4px', backgroundColor: '#f1f5f9' }}>v{app.version}</span>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                <div style={{ padding: '20px 24px', flex: 1 }}>
                                    <p style={{ margin: 0, fontSize: '0.9rem', color: '#475569', lineHeight: 1.5, display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>
                                        {app.description || 'No description available for this application.'}
                                    </p>

                                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px', marginTop: '20px' }}>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '0.8rem', color: '#64748b' }}>
                                            <Calendar size={14} />
                                            <span>Created: {new Date(app.created_at).toLocaleDateString()}</span>
                                        </div>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', fontSize: '0.8rem', color: '#64748b' }}>
                                            <ShieldCheck size={14} />
                                            <span>Status: {app.approval_status || 'DRAFT'}</span>
                                        </div>
                                    </div>
                                </div>

                                <div style={{ padding: '16px 24px', backgroundColor: '#f8fafc', borderTop: '1px solid #f1f5f9', display: 'flex', justifyContent: 'flex-end' }}>
                                    <button
                                        onClick={() => handleUninstall(app.id, app.name)}
                                        style={{
                                            display: 'flex', alignItems: 'center', gap: '8px',
                                            padding: '10px 20px', borderRadius: '8px', border: '1px solid #fecaca',
                                            backgroundColor: 'white', color: '#dc2626', fontWeight: 700, cursor: 'pointer',
                                            transition: 'all 0.2s'
                                        }}
                                        onMouseEnter={(e) => { e.currentTarget.style.backgroundColor = '#fef2f2'; }}
                                        onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = 'white'; }}
                                    >
                                        <Trash2 size={16} />
                                        Uninstall App
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div style={{ backgroundColor: 'white', borderRadius: '12px', border: '1px solid #e2e8f0', overflow: 'hidden' }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                            <thead style={{ backgroundColor: '#f8fafc', borderBottom: '1px solid #e2e8f0' }}>
                                <tr>
                                    <th style={{ padding: '12px 24px', fontSize: '0.75rem', fontWeight: 800, color: '#64748b', textTransform: 'uppercase' }}>Application</th>
                                    <th style={{ padding: '12px 24px', fontSize: '0.75rem', fontWeight: 800, color: '#64748b', textTransform: 'uppercase' }}>Category</th>
                                    <th style={{ padding: '12px 24px', fontSize: '0.75rem', fontWeight: 800, color: '#64748b', textTransform: 'uppercase' }}>Status</th>
                                    <th style={{ padding: '12px 24px', fontSize: '0.75rem', fontWeight: 800, color: '#64748b', textTransform: 'uppercase' }}>Created</th>
                                    <th style={{ padding: '12px 24px' }}></th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredApps.map(app => (
                                    <tr key={app.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                                        <td style={{ padding: '16px 24px' }}>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                                                <div style={{ width: '40px', height: '40px', borderRadius: '8px', backgroundColor: '#f0f7ff', border: '1px solid #bfdbfe', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#2563eb' }}>
                                                    <Layout size={20} />
                                                </div>
                                                <div>
                                                    <div style={{ fontWeight: 800, fontSize: '0.95rem', color: '#1e293b' }}>{app.name || 'Untitled App'}</div>
                                                    <div style={{ fontSize: '0.75rem', color: '#64748b', marginTop: '4px' }}>{app.version ? `v${app.version}` : 'v1.0'}</div>
                                                </div>
                                            </div>
                                        </td>
                                        <td style={{ padding: '16px 24px' }}>
                                            <span style={{ padding: '4px 10px', borderRadius: '20px', backgroundColor: '#f8fafc', border: '1px solid #e2e8f0', fontSize: '0.75rem', fontWeight: 600, color: '#475569' }}>
                                                {getAppCategory(app)}
                                            </span>
                                        </td>
                                        <td style={{ padding: '16px 24px', fontSize: '0.85rem', color: '#475569', fontWeight: 500 }}>{app.approval_status || 'DRAFT'}</td>
                                        <td style={{ padding: '16px 24px', fontSize: '0.85rem', color: '#475569', fontWeight: 500 }}>{new Date(app.created_at).toLocaleDateString()}</td>
                                        <td style={{ padding: '16px 24px', textAlign: 'right' }}>
                                            <button
                                                onClick={() => handleUninstall(app.id, app.name)}
                                                style={{
                                                    padding: '8px 16px', borderRadius: '6px', border: '1px solid #fecaca',
                                                    backgroundColor: 'white', color: '#dc2626', fontWeight: 700, cursor: 'pointer', fontSize: '0.8rem',
                                                    display: 'inline-flex', alignItems: 'center', gap: '6px', transition: 'all 0.2s'
                                                }}
                                                onMouseEnter={(e) => { e.currentTarget.style.backgroundColor = '#fef2f2'; }}
                                                onMouseLeave={(e) => { e.currentTarget.style.backgroundColor = 'white'; }}
                                            >
                                                <Trash2 size={14} />
                                                Uninstall
                                            </button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        </div>
    );
};

export default AppManagement;

src/components/AppPlayer.jsx.content:
import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
    Search, Play, Square, RefreshCw, ExternalLink, User, MapPin,
    Rocket, Clock3, Package, Maximize2, Minimize2, Star,
    AlertTriangle, RotateCcw, X, ChevronRight, Pause, MessageSquare, Info, Code, Play as PlayIcon,
    Wifi, Cpu, HardDrive, CheckCircle2, XCircle, AlertCircle, Signal, Bug,
    Languages, Camera, PenTool, Globe, Plus, FilePlus, Settings2, Sparkles, CheckCircle2 as CheckIcon
} from 'lucide-react';
import { getAllFrontlineApps, getProductionQueue, logPlayerSession, saveFrontlineApp } from '../utils/supabaseFrontlineDB';
import { getStations, getEdgeDevices, createTable, getTables } from '../utils/database';
import iotConnector from '../utils/iotConnector';
import { useLanguage } from '../contexts/LanguageContext';
import { createIncomingInspectionTemplate } from '../utils/incomingInspectionTemplate';

// ─── helpers ────────────────────────────────────────────────────────────────

const LS_FAVORITES = 'mavi_player_favorites';
const LS_RECENT = 'mavi_player_recent';
const LS_DEV_MODE = 'mavi_player_dev_mode';
const RECENT_MAX = 5;

function loadLS(key, fallback) {
    try { return JSON.parse(localStorage.getItem(key)) ?? fallback; }
    catch { return fallback; }
}

function saveLS(key, value) {
    try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* noop */ }
}

function nameToHue(str = '') {
    let hash = 0;
    for (let i = 0; i < str.length; i++) hash = str.charCodeAt(i) + ((hash << 5) - hash);
    return Math.abs(hash) % 360;
}

function appGradient(name) {
    const h = nameToHue(name);
    return `linear-gradient(135deg, hsl(${h},70%,55%) 0%, hsl(${(h + 40) % 360},80%,40%) 100%)`;
}

const formatDuration = (secs) => {
    const m = Math.floor(secs / 60);
    const s = secs % 60;
    return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
};

// ─── sub-components ──────────────────────────────────────────────────────────

function FilterTabs({ active, onChange }) {
    const tabs = ['All', 'Recent', 'Favorites', 'Pending'];
    return (
        <div style={{ display: 'flex', gap: '4px', marginBottom: '10px' }}>
            {tabs.map((t) => (
                <button
                    key={t}
                    onClick={() => onChange(t)}
                    style={{
                        flex: 1,
                        padding: '6px 0',
                        border: 'none',
                        borderRadius: '8px',
                        fontSize: '0.72rem',
                        fontWeight: 700,
                        cursor: 'pointer',
                        backgroundColor: active === t ? '#2563eb' : '#f1f5f9',
                        color: active === t ? 'white' : '#64748b',
                        transition: 'all 0.15s'
                    }}
                >
                    {t}
                </button>
            ))}
        </div>
    );
}

function AppCard({ app, isActive, isFavorite, isRecent, onLaunch, onFavorite }) {
    const gradient = appGradient(app.name);
    const bgImage = app.config?.thumbnail ? `url(${app.config.thumbnail})` : gradient;

    const getStatusStyle = (status) => {
        if (status === 'PUBLISHED') return { bg: '#dcfce7', text: '#166534' };
        if (status === 'PENDING') return { bg: '#fef9c3', text: '#854d0e' };
        return { bg: '#f1f5f9', text: '#475569' };
    };
    const statusStyle = getStatusStyle(app.approval_status || 'DRAFT');

    return (
        <div
            style={{
                borderRadius: '12px',
                border: `1px solid ${isActive ? '#93c5fd' : '#e2e8f0'}`,
                backgroundColor: isActive ? '#eff6ff' : '#fff',
                marginBottom: '10px',
                overflow: 'hidden',
                boxShadow: isActive ? '0 0 0 2px rgba(59,130,246,0.2)' : 'none',
                transition: 'box-shadow 0.2s, border-color 0.2s'
            }}
        >
            {/* thumbnail */}
            <div style={{
                height: '64px',
                background: bgImage,
                backgroundSize: 'cover',
                backgroundPosition: 'center',
                display: 'flex',
                alignItems: 'flex-start',
                justifyContent: 'space-between',
                padding: '8px 12px',
                position: 'relative'
            }}>
                {/* Overlay gradient for text readability if using an image */}
                {app.config?.thumbnail && (
                    <div style={{ position: 'absolute', inset: 0, background: 'linear-gradient(to bottom, rgba(0,0,0,0.4) 0%, transparent 100%)' }} />
                )}

                <div style={{ display: 'flex', flexDirection: 'column', gap: '4px', position: 'relative', zIndex: 1 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                        <Rocket size={16} color="white" />
                        <span style={{ fontSize: '0.82rem', fontWeight: 800, color: 'white', textShadow: '0 1px 3px rgba(0,0,0,0.5)' }}>
                            {app.name}
                        </span>
                    </div>
                    <div style={{ display: 'flex', gap: '6px' }}>
                        <span style={{ fontSize: '0.6rem', fontWeight: 700, backgroundColor: statusStyle.bg, color: statusStyle.text, padding: '1px 6px', borderRadius: '4px' }}>
                            {app.approval_status || 'DRAFT'}
                        </span>
                        <span style={{ fontSize: '0.6rem', fontWeight: 700, backgroundColor: 'rgba(0,0,0,0.4)', color: 'white', padding: '1px 6px', borderRadius: '4px', backdropFilter: 'blur(2px)' }}>
                            v{app.version || 1}
                        </span>
                    </div>
                </div>
                <div style={{ display: 'flex', alignItems: 'center', gap: '6px', position: 'absolute', right: '12px', top: '8px', zIndex: 1 }}>
                    <button
                        onClick={(e) => { e.stopPropagation(); onFavorite(app.id); }}
                        title={isFavorite ? 'Remove from Favorites' : 'Add to Favorites'}
                        style={{
                            background: 'rgba(255,255,255,0.2)',
                            border: 'none',
                            borderRadius: '6px',
                            padding: '4px',
                            cursor: 'pointer',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            color: isFavorite ? '#fde68a' : 'rgba(255,255,255,0.7)',
                            transition: 'color 0.15s'
                        }}
                    >
                        <Star size={14} fill={isFavorite ? '#fde68a' : 'none'} />
                    </button>
                </div>
            </div>

            {/* actions */}
            <div style={{ padding: '8px 10px', display: 'flex', gap: '6px', alignItems: 'center' }}>
                {isRecent && (
                    <span style={{ fontSize: '0.65rem', fontWeight: 700, color: '#7c3aed', backgroundColor: '#f3e8ff', borderRadius: '4px', padding: '2px 6px' }}>
                        Recent
                    </span>
                )}
                {app.category && (
                    <span style={{ fontSize: '0.65rem', fontWeight: 700, color: '#0369a1', backgroundColor: '#e0f2fe', borderRadius: '4px', padding: '2px 6px' }}>
                        {app.category}
                    </span>
                )}
                <button
                    onClick={() => onLaunch(app)}
                    style={{
                        marginLeft: 'auto',
                        padding: '6px 12px',
                        borderRadius: '8px',
                        border: `1px solid ${isActive ? '#3b82f6' : '#3b82f6'}`,
                        backgroundColor: isActive ? '#3b82f6' : '#eff6ff',
                        color: isActive ? 'white' : '#2563eb',
                        fontWeight: 700,
                        fontSize: '0.75rem',
                        cursor: 'pointer',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '5px',
                        transition: 'all 0.15s'
                    }}
                >
                    <Play size={12} />
                    {isActive ? 'Running' : 'Launch'}
                </button>
            </div>
        </div>
    );
}

function AuthModal({ app, operatorDefault, stationDefault, stations = [], onConfirm, onCancel }) {
    const [opName, setOpName] = useState(operatorDefault || '');
    const [stn, setStn] = useState(stationDefault || (stations[0]?.id || ''));
    const [isScanning, setIsScanning] = useState(false);
    const badgeBuffer = useRef('');
    const lastKeyTime = useRef(0);
    const hue = nameToHue(app?.name || '');

    useEffect(() => {
        const handleKeyDown = (e) => {
            const now = Date.now();

            // Fast typing (scanner simulation)
            if (now - lastKeyTime.current < 50) {
                setIsScanning(true);
            }

            if (e.key === 'Enter') {
                if (badgeBuffer.current.length > 2) {
                    // Valid badge scanned
                    const scannedValue = badgeBuffer.current;
                    setOpName(scannedValue);
                    onConfirm(scannedValue, stn || 'Station-01');
                }
                badgeBuffer.current = '';
                setIsScanning(false);
            } else if (e.key.length === 1) {
                badgeBuffer.current += e.key;
            }

            lastKeyTime.current = now;

            // Reset buffer if idle for too long
            setTimeout(() => {
                if (Date.now() - lastKeyTime.current > 100) {
                    badgeBuffer.current = '';
                    setIsScanning(false);
                }
            }, 150);
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [stn, onConfirm]);

    return (
        <div style={{
            position: 'fixed', inset: 0, backgroundColor: 'rgba(15,23,42,0.6)',
            display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 9999,
            backdropFilter: 'blur(4px)'
        }}>
            <div style={{
                backgroundColor: 'white', borderRadius: '16px', width: '380px',
                boxShadow: '0 20px 60px rgba(0,0,0,0.3)', overflow: 'hidden'
            }}>
                <div style={{ background: appGradient(app?.name || ''), padding: '20px', position: 'relative' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                        <div>
                            <div style={{ fontSize: '0.7rem', fontWeight: 700, color: 'rgba(255,255,255,0.7)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                                Launch App
                            </div>
                            <div style={{ fontSize: '1.1rem', fontWeight: 800, color: 'white', marginTop: '3px' }}>
                                {app?.name}
                            </div>
                        </div>
                        <button onClick={onCancel} style={{ background: 'rgba(255,255,255,0.2)', border: 'none', borderRadius: '6px', cursor: 'pointer', padding: '4px', color: 'white', display: 'flex' }}>
                            <X size={16} />
                        </button>
                    </div>
                </div>

                <div style={{ padding: '20px' }}>
                    {isScanning && (
                        <div style={{ 
                            marginBottom: '14px', padding: '10px', borderRadius: '8px', 
                            backgroundColor: '#eff6ff', border: '1px dashed #3b82f6',
                            display: 'flex', alignItems: 'center', gap: '8px',
                            animation: 'pulse 1.5s infinite'
                        }}>
                            <Rocket size={14} color="#3b82f6" />
                            <span style={{ fontSize: '0.75rem', fontWeight: 700, color: '#1d4ed8' }}>Waiting for Badge Scan...</span>
                        </div>
                    )}

