            }}>

                {/* ── SIDEBAR ──────────────────────────────────────────────── */}
                <div style={{
                    ...panelStyle,
                    display: 'flex',
                    flexDirection: 'column',
                    overflow: 'hidden',
                    opacity: sidebarHidden ? 0 : 1,
                    pointerEvents: sidebarHidden ? 'none' : 'auto',
                    transition: 'opacity 0.2s'
