                            </div>
                            <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                <div style={{ 
                                    fontSize: '0.65rem', fontWeight: 800, padding: '3px 8px', borderRadius: '20px',
                                    backgroundColor: isOnline ? '#dcfce7' : '#fee2e2',
