    const newAllAutos = allAutos.filter(a => a.id !== updatedAuto.id);
    newAllAutos.push(updatedAuto);
    localStorage.setItem('mes_automations', JSON.stringify(newAllAutos));
    setCurrentAuto(updatedAuto);

