                {msg.role === 'assistant' ? (
                  <div style={{ width: '22px', height: '22px', borderRadius: '7px', background: 'linear-gradient(135deg,#6366f1,#3b82f6)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
