                    type: 'KPI',
                    tableId: 'SYSTEM:COMPLETIONS',
                    xAxisColumn: 'status',
                    yAxisColumn: 'id',
                    aggregation: 'COUNT',
                    color: '#0ea5e9',
                    kpiLabel: 'Total Unit Selesai'
                }
