src/components/EdgeDeviceManager.jsx.content:
import React, { useState, useEffect } from 'react';
import { 
    Cpu, 
    Plus, 
    Search, 
    Settings, 
    Activity, 
    Zap, 
    Trash2, 
    AlertTriangle,
    CheckCircle2,
    XCircle,
    Info,
    ArrowRight,
    Wifi,
    HardDrive
} from 'lucide-react';
import { getEdgeDevices, saveEdgeDevice, deleteEdgeDevice } from '../utils/database';

const EdgeDeviceManager = () => {
    const [devices, setDevices] = useState([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
    const [newDeviceData, setNewDeviceData] = useState({
        name: '',
        model: 'Edge IO',
        serialNumber: ''
    });

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        const d = await getEdgeDevices();
        setDevices(d);
    };

    const handleCreateDevice = async () => {
        if (!newDeviceData.name) return;

        const device = {
            ...newDeviceData,
            status: 'ONLINE',
            lastSeen: new Date().toISOString(),
            ipAddress: '192.168.1.' + Math.floor(Math.random() * 254 + 1),
            firmware: 'v5.2.1'
        };

        await saveEdgeDevice(device);
        setIsCreateModalOpen(false);
        setNewDeviceData({ name: '', model: 'Edge IO', serialNumber: '' });
        loadData();
    };

    const handleDeleteDevice = async (id) => {
        if (window.confirm('Are you sure you want to remove this edge device?')) {
            await deleteEdgeDevice(id);
            loadData();
        }
    };

    const filteredDevices = devices.filter(d => 
        d.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        d.serialNumber.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div style={{ height: '100%', display: 'flex', flexDirection: 'column', backgroundColor: '#f8fafc' }}>
            <div style={{ padding: '24px', borderBottom: '1px solid #e2e8f0', backgroundColor: 'white', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                    <h2 style={{ margin: 0, fontSize: '1.5rem', fontWeight: 900, color: '#0f172a' }}>Edge Devices</h2>
                    <p style={{ margin: '4px 0 0 0', color: '#64748b', fontSize: '0.9rem' }}>Manage Edge IO and Edge MC hardware</p>
                </div>
                <button 
                    onClick={() => setIsCreateModalOpen(true)}
                    style={{ 
                        display: 'flex', alignItems: 'center', gap: '8px', 
                        padding: '10px 20px', backgroundColor: '#3b82f6', color: 'white', 
                        border: 'none', borderRadius: '8px', fontWeight: 700, cursor: 'pointer' 
                    }}
                >
                    <Plus size={18} /> Register Edge Device
                </button>
            </div>

            <div style={{ padding: '24px', flex: 1, overflowY: 'auto' }}>
                <div style={{ position: 'relative', maxWidth: '400px', marginBottom: '32px' }}>
                    <Search style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: '#94a3b8' }} size={16} />
                    <input 
                        type="text" 
                        placeholder="Search devices..." 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        style={{ 
                            width: '100%', padding: '12px 12px 12px 40px', 
                            borderRadius: '10px', border: '1px solid #e2e8f0', backgroundColor: 'white' 
                        }} 
                    />
                </div>

                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(350px, 1fr))', gap: '24px' }}>
                    {filteredDevices.map(device => (
                        <div key={device.id} style={{ backgroundColor: 'white', borderRadius: '16px', border: '1px solid #e2e8f0', overflow: 'hidden', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.05)' }}>
                            <div style={{ padding: '20px', borderBottom: '1px solid #f1f5f9', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                                    <div style={{ width: '40px', height: '40px', borderRadius: '10px', backgroundColor: '#f0f9ff', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#3b82f6' }}>
                                        <HardDrive size={20} />
                                    </div>
                                    <div>
                                        <div style={{ fontWeight: 800, color: '#1e293b' }}>{device.name}</div>
                                        <div style={{ fontSize: '0.75rem', fontWeight: 600, color: '#64748b' }}>{device.model}</div>
                                    </div>
                                </div>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '6px', fontSize: '0.7rem', fontWeight: 800, color: '#10b981', backgroundColor: '#dcfce7', padding: '4px 10px', borderRadius: '20px' }}>
                                    ONLINE
                                </div>
                            </div>
                            <div style={{ padding: '20px' }}>
                                <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginBottom: '20px' }}>
                                    <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem' }}>
                                        <span style={{ color: '#64748b' }}>Serial Number</span>
                                        <span style={{ fontWeight: 600 }}>{device.serialNumber || 'N/A'}</span>
                                    </div>
                                    <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem' }}>
                                        <span style={{ color: '#64748b' }}>IP Address</span>
                                        <span style={{ fontWeight: 600 }}>{device.ipAddress}</span>
                                    </div>
                                    <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem' }}>
                                        <span style={{ color: '#64748b' }}>Firmware</span>
                                        <span style={{ fontWeight: 600 }}>{device.firmware}</span>
                                    </div>
                                </div>
                                <div style={{ display: 'flex', gap: '10px' }}>
                                    <button style={{ flex: 1, padding: '10px', borderRadius: '8px', border: '1px solid #e2e8f0', backgroundColor: 'white', fontWeight: 700, cursor: 'pointer', fontSize: '0.8rem' }}>Configure I/O</button>
                                    <button style={{ padding: '10px', borderRadius: '8px', border: '1px solid #fee2e2', color: '#ef4444', backgroundColor: 'white', cursor: 'pointer' }} onClick={() => handleDeleteDevice(device.id)}>
                                        <Trash2 size={16} />
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>

                {filteredDevices.length === 0 && (
                    <div style={{ textAlign: 'center', padding: '80px', backgroundColor: 'white', borderRadius: '16px', border: '1px dashed #cbd5e1' }}>
                        <HardDrive size={48} color="#cbd5e1" style={{ marginBottom: '16px' }} />
                        <h3 style={{ margin: 0, color: '#1e293b' }}>No edge devices registered</h3>
                        <p style={{ color: '#64748b', maxWidth: '300px', margin: '8px auto' }}>Register your Edge IO or Edge MC to bridge the physical floor with MES.</p>
                        <button 
                            onClick={() => setIsCreateModalOpen(true)}
                            style={{ marginTop: '16px', padding: '10px 24px', backgroundColor: '#3b82f6', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 700, cursor: 'pointer' }}
                        >
                            Register Device
                        </button>
                    </div>
                )}
            </div>

            {/* Create Modal */}
            {isCreateModalOpen && (
                <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 2000 }}>
                    <div style={{ backgroundColor: 'white', width: '500px', borderRadius: '16px', overflow: 'hidden' }}>
                        <div style={{ padding: '24px', borderBottom: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <h2 style={{ margin: 0, fontSize: '1.25rem', fontWeight: 800 }}>Register Edge Device</h2>
                            <button onClick={() => setIsCreateModalOpen(false)} style={{ border: 'none', background: 'none', cursor: 'pointer' }}><XCircle size={20} color="#94a3b8" /></button>
                        </div>
                        <div style={{ padding: '24px', display: 'flex', flexDirection: 'column', gap: '20px' }}>
                            <div>
                                <label style={{ fontSize: '0.75rem', fontWeight: 800, color: '#64748b', textTransform: 'uppercase', marginBottom: '8px', display: 'block' }}>Display Name</label>
                                <input 
                                    type="text" 
                                    style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #e2e8f0' }}
                                    placeholder="e.g. Assembly Line Edge IO"
                                    value={newDeviceData.name}
                                    onChange={(e) => setNewDeviceData({ ...newDeviceData, name: e.target.value })}
                                />
                            </div>
                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
                                <div>
                                    <label style={{ fontSize: '0.75rem', fontWeight: 800, color: '#64748b', textTransform: 'uppercase', marginBottom: '8px', display: 'block' }}>Model</label>
                                    <select 
                                        style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #e2e8f0', backgroundColor: 'white' }}
                                        value={newDeviceData.model}
                                        onChange={(e) => setNewDeviceData({ ...newDeviceData, model: e.target.value })}
                                    >
                                        <option>Edge IO</option>
                                        <option>Edge MC</option>
                                        <option>I/O Gateway</option>
                                    </select>
                                </div>
                                <div>
                                    <label style={{ fontSize: '0.75rem', fontWeight: 800, color: '#64748b', textTransform: 'uppercase', marginBottom: '8px', display: 'block' }}>Serial Number</label>
                                    <input 
                                        type="text" 
                                        style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #e2e8f0' }}
                                        placeholder="e.g. EIO-12345"
                                        value={newDeviceData.serialNumber}
                                        onChange={(e) => setNewDeviceData({ ...newDeviceData, serialNumber: e.target.value })}
                                    />
                                </div>
                            </div>
                        </div>
                        <div style={{ padding: '24px', backgroundColor: '#f8fafc', borderTop: '1px solid #e2e8f0', display: 'flex', justifyContent: 'flex-end', gap: '12px' }}>
                            <button 
                                onClick={() => setIsCreateModalOpen(false)}
                                style={{ padding: '10px 20px', borderRadius: '8px', border: '1px solid #e2e8f0', backgroundColor: 'white', fontWeight: 700, cursor: 'pointer' }}
                            >
                                Cancel
                            </button>
                            <button 
                                onClick={handleCreateDevice}
                                style={{ padding: '10px 24px', borderRadius: '8px', backgroundColor: '#3b82f6', color: 'white', border: 'none', fontWeight: 700, cursor: 'pointer' }}
                            >
                                Register
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default EdgeDeviceManager;

src/components/FrontlineCopilot.jsx.content:
import React, { useState, useEffect, useRef } from 'react';
import { 
  MessageSquare, 
  Send, 
  X, 
  Sparkles, 
  User, 
  Bot, 
  Loader2,
  Trash2,
  BrainCircuit,
  Settings
} from 'lucide-react';
import { getIntegrationConnectors } from '../utils/database';

const FrontlineCopilot = ({ isOpen, onClose, appContext, selectedApp }) => {
  const [messages, setMessages] = useState([
    { role: 'assistant', content: 'Halo! Saya Frontline Copilot. Ada yang bisa saya bantu dengan pekerjaan Anda hari ini?', timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [aiConnector, setAiConnector] = useState(null);
  const scrollRef = useRef(null);

  useEffect(() => {
    const loadAiConfig = async () => {
      const allConnectors = await getIntegrationConnectors();
      const aiConn = allConnectors.find(c => c.type === 'AI_ASSISTANT');
      setAiConnector(aiConn);
    };
    if (isOpen) loadAiConfig();
  }, [isOpen]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage = { role: 'user', content: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    try {
      // Logic for real AI call would go here using aiConnector
      // For now, we simulate a smart response based on context
      await new Promise(r => setTimeout(r, 1500));

      let responseContent = "Maaf, saya sedang dalam mode simulasi. Harap konfigurasi konektor AI di modul Integrasi.";

      const settings = aiConnector?.aiSettings || aiConnector?.config;
      if (!aiConnector || !settings?.apiKey) {
        responseContent = "Konektor AI belum dikonfigurasi sepenuhnya. Buka 'Integrations' lalu tambah konektor 'AI Assistant' dengan API Key Anda.";
      } else {
        // Simulated smart response
        const lowerInput = input.toLowerCase();
        const currentStep = (selectedApp?.config?.steps || [])[appContext.currentStepIndex]?.title || 'Langkah Saat Ini';

        if (lowerInput.includes('bagaimana') || lowerInput.includes('cara') || lowerInput.includes('bantu')) {
          responseContent = `Tentu! Untuk langkah "${currentStep}", pastikan Anda mengikuti SOP dengan teliti. Jika ada masalah pada mesin, harap lapor melalui sistem Andon. Apa ada detail spesifik yang ingin Anda tanyakan?`;
        } else if (lowerInput.includes('oee') || lowerInput.includes('performa')) {
          responseContent = `Performa mesin saat ini terpantau stabil. Pastikan input hasil produksi dicatat tepat waktu agar kalkulasi OEE akurat.`;
        } else {
          responseContent = `Saya mengerti pertanyaan Anda mengenai "${input}". Sebagai asisten manufaktur, saya menyarankan Anda untuk memeriksa manual mesin jika ada kendala teknis.`;
        }
      }

      setMessages(prev => [...prev, { 
        role: 'assistant', 
        content: responseContent, 
        timestamp: new Date() 
      }]);
    } catch (err) {
      console.error('Copilot Error:', err);
    } finally {
      setIsLoading(false);
    }
  };

  if (!isOpen) return null;

  return (
    <div style={{
      position: 'fixed',
      top: '80px',
      right: '24px',
      bottom: '24px',
      width: '400px',
      backgroundColor: 'white',
      borderRadius: '16px',
      display: 'flex',
      flexDirection: 'column',
      boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1), 0 10px 10px -5px rgba(0,0,0,0.04)',
      border: '1px solid #e2e8f0',
      zIndex: 1000,
      overflow: 'hidden'
    }}>
      {/* Header */}
      <div style={{ padding: '16px 20px', borderBottom: '1px solid #e2e8f0', backgroundColor: '#0f172a', color: 'white', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <div style={{ backgroundColor: 'rgba(59,130,246,0.2)', padding: '8px', borderRadius: '10px' }}>
            <Sparkles size={20} color="#60a5fa" />
          </div>
          <div>
            <div style={{ fontSize: '0.95rem', fontWeight: 800 }}>Frontline Copilot</div>
            <div style={{ fontSize: '0.65rem', color: '#94a3b8', display: 'flex', alignItems: 'center', gap: '4px' }}>
              <BrainCircuit size={10} /> {aiConnector ? `${aiConnector.aiSettings?.provider || aiConnector.config?.provider || ''} (${aiConnector.aiSettings?.modelId || aiConnector.config?.modelId || ''})` : 'System Simulation'}
            </div>
          </div>
        </div>
        <button onClick={onClose} style={{ background: 'none', border: 'none', color: '#94a3b8', cursor: 'pointer', padding: '4px' }}>
          <X size={20} />
        </button>
      </div>

      {/* Messages */}
      <div 
        ref={scrollRef}
        style={{ flex: 1, padding: '20px', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '16px', backgroundColor: '#f8fafc' }}
      >
        {messages.map((msg, idx) => (
          <div key={idx} style={{ display: 'flex', flexDirection: 'column', alignItems: msg.role === 'user' ? 'flex-end' : 'flex-start', gap: '4px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '6px', marginBottom: '2px' }}>
              {msg.role === 'assistant' ? <Bot size={14} color="#64748b" /> : <User size={14} color="#64748b" />}
              <span style={{ fontSize: '0.65rem', fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase' }}>{msg.role === 'user' ? 'You' : 'Copilot'}</span>
            </div>
            <div style={{
              maxWidth: '85%',
              padding: '12px 16px',
              borderRadius: msg.role === 'user' ? '16px 4px 16px 16px' : '4px 16px 16px 16px',
              backgroundColor: msg.role === 'user' ? '#3b82f6' : 'white',
              color: msg.role === 'user' ? 'white' : '#1e293b',
              fontSize: '0.85rem',
              lineHeight: 1.5,
              border: msg.role === 'user' ? 'none' : '1px solid #e2e8f0',
              boxShadow: msg.role === 'user' ? '0 4px 6px -1px rgba(59, 130, 246, 0.2)' : '0 2px 4px rgba(0,0,0,0.02)'
            }}>
              {msg.content}
            </div>
          </div>
        ))}
        {isLoading && (
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#94a3b8', fontSize: '0.8rem' }}>
            <Loader2 className="animate-spin" size={16} />
            <span>Copilot sedang berpikir...</span>
          </div>
        )}
      </div>

      {/* Input */}
      <div style={{ padding: '20px', borderTop: '1px solid #e2e8f0', backgroundColor: 'white' }}>
        <div style={{ position: 'relative' }}>
          <input 
            value={input}
            onChange={e => setInput(e.target.value)}
            onKeyPress={e => e.key === 'Enter' && handleSend()}
            placeholder="Ketik pesan..."
            style={{ 
              width: '100%', 
              padding: '12px 44px 12px 16px', 
              borderRadius: '24px', 
              border: '1px solid #e2e8f0',
              backgroundColor: '#f1f5f9',
              fontSize: '0.9rem',
              outline: 'none',
              transition: 'border-color 0.2s'
            }}
          />
          <button 
            onClick={handleSend}
            disabled={!input.trim() || isLoading}
            style={{ 
              position: 'absolute', 
              right: '8px', 
              top: '50%', 
              transform: 'translateY(-50%)',
              backgroundColor: '#3b82f6',
              color: 'white',
              border: 'none',
              width: '32px',
              height: '32px',
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              cursor: (input.trim() && !isLoading) ? 'pointer' : 'default',
              opacity: (input.trim() && !isLoading) ? 1 : 0.5,
              transition: 'all 0.2s'
            }}
          >
            <Send size={16} />
          </button>
        </div>
        <div style={{ marginTop: '12px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div style={{ fontSize: '0.65rem', color: '#94a3b8', display: 'flex', alignItems: 'center', gap: '4px' }}>
            <Settings size={12} /> Terhubung ke {selectedApp?.name || 'Aplikasi'}
          </div>
          <button onClick={() => setMessages([{ role: 'assistant', content: 'Riwayat percakapan dibersihkan.', timestamp: new Date() }])} style={{ background: 'none', border: 'none', color: '#94a3b8', fontSize: '0.65rem', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '4px' }}>
            <Trash2 size={12} /> Bersihkan
          </button>
        </div>
      </div>
    </div>
  );
};

export default FrontlineCopilot;

