import React, { useState, useEffect } from 'react';
import { Activity, AlertCircle, CheckCircle2, Clock, Map, TrendingUp, Users, Zap, MessageSquare } from 'lucide-react';
import { getSupabaseClient, isSupabaseReady } from '../utils/supabaseManualDB.js';
import { acknowledgeAndon, getShopFloorRealtimeSnapshot } from '../utils/supabaseFrontlineDB.js';
import ChatWidget from './ChatWidget';
import { getCurrentUser } from '../utils/auth';

const Home = () => {
  const [activeAndons, setActiveAndons] = useState([]);
  const [workstations, setWorkstations] = useState([]);
  const [oeeToday, setOeeToday] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showChat, setShowChat] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  const showChatRef = React.useRef(showChat);
  const currentUser = getCurrentUser()?.name || 'Manager';

  useEffect(() => {
    showChatRef.current = showChat;
    if (showChat) setUnreadCount(0);
  }, [showChat]);

  const refreshSnapshot = async ({ silent = false } = {}) => {
    if (!silent) setLoading(true);
    setError('');
    try {
      const snap = await getShopFloorRealtimeSnapshot();
      setWorkstations(snap.workstations || []);
      setActiveAndons(snap.activeAndons || []);
      setOeeToday(typeof snap.oee === 'number' ? snap.oee : 0);
    } catch (err) {
      console.error('[Home] Failed to fetch realtime snapshot', err);
      setError('Gagal load data realtime. Pastikan koneksi Supabase aktif.');
    } finally {
      if (!silent) setLoading(false);
    }
  };

  useEffect(() => {
    let isMounted = true;
    let realtimeChannel = null;
    let pollingInterval = null;

    const initial = async () => {
      if (!isMounted) return;
      await refreshSnapshot();
    };

    initial();

    if (!isSupabaseReady()) {
      console.warn('[Home] Supabase is not configured. Realtime features (Chat, Notifications) will be disabled.');
      pollingInterval = setInterval(() => refreshSnapshot({ silent: true }), 10000);
      return () => {
        isMounted = false;
        if (pollingInterval) clearInterval(pollingInterval);
      };
    }

    const supabase = getSupabaseClient();

    try {
      realtimeChannel = supabase
        .channel(`shop-floor-home-${Date.now()}`)
        .on('postgres_changes', { event: '*', schema: 'public', table: 'production_queue' }, () => {
          refreshSnapshot({ silent: true });
        })
        .on('postgres_changes', { event: '*', schema: 'public', table: 'audit_logs' }, () => {
          refreshSnapshot({ silent: true });
        })
        .subscribe((status) => {
          if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT') {
            if (!pollingInterval) {
              pollingInterval = setInterval(() => refreshSnapshot({ silent: true }), 10000);
            }
          }
        });

      // Safety polling for environments where realtime may be blocked.
      pollingInterval = setInterval(() => refreshSnapshot({ silent: true }), 10000);
    } catch (e) {
      console.warn('[Home] Realtime subscription unavailable, fallback polling only.', e);
      pollingInterval = setInterval(() => refreshSnapshot({ silent: true }), 10000);
    }

    // Chat Notification Listener
    const chatChannel = supabase
      .channel('chat_notifications')
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'chat_messages' 
      }, (payload) => {
        const msg = payload.new;
        // If chat is closed, increment unread count
        if (!showChatRef.current) {
          setUnreadCount(prev => prev + 1);
          // Play a subtle notification sound
          try {
            const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2358/2358-preview.mp3');
            audio.play();
          } catch (e) {}
        }
      })
      .subscribe();

    return () => {
      isMounted = false;
      if (pollingInterval) clearInterval(pollingInterval);
      if (realtimeChannel) {
        try {
          realtimeChannel.unsubscribe();
        } catch (e) {
          console.warn('[Home] Failed to unsubscribe realtime channel', e);
        }
      }
      if (chatChannel) chatChannel.unsubscribe();
    };
  }, [showChat]);

  // Timer to update "Elapsed Time" for active Andons
  const [currentTime, setCurrentTime] = useState(Date.now());
  useEffect(() => {
    if (activeAndons.length === 0) return;
    const interval = setInterval(() => setCurrentTime(Date.now()), 1000);
    return () => clearInterval(interval);
  }, [activeAndons.length]);

  const formatElapsed = (startTime) => {
    const seconds = Math.floor((currentTime - startTime) / 1000);
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'RUNNING': return { bg: '#eff6ff', text: '#2563eb', border: '#bfdbfe', accent: '#2563eb', icon: <Activity size={14} /> };
      case 'READY': return { bg: '#f8fafc', text: '#475569', border: '#e2e8f0', accent: '#94a3b8', icon: <CheckCircle2 size={14} /> };
      case 'DOWN': return { bg: '#fef2f2', text: '#dc2626', border: '#fecaca', accent: '#ef4444', icon: <AlertCircle size={14} /> };
      default: return { bg: '#f8fafc', text: '#475569', border: '#e2e8f0', accent: '#94a3b8', icon: <Clock size={14} /> };
    }
  };

  const getInitials = (name) => {
    if (!name || name === 'N/A') return '??';
    return name.split(' ').map(n => n[0]).join('').toUpperCase().substring(0, 2);
  };

  return (
    <div style={{ 
      padding: '30px', 
      backgroundColor: '#f8fafc', 
      minHeight: '100vh', 
      fontFamily: "'Inter', sans-serif",
      width: '100%',
      boxSizing: 'border-box'
    }}>

      {/* HEADER */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
        <div>
          <h1 style={{ margin: 0, fontSize: '2rem', fontWeight: 900, color: '#0f172a', display: 'flex', alignItems: 'center', gap: '10px' }}>
            <Map size={28} color="#3b82f6" /> Shop Floor Overview
          </h1>
          <p style={{ margin: '5px 0 0 0', color: '#64748b' }}>Real-time monitoring and Andon response dashboard</p>
        </div>
        <div style={{ display: 'flex', gap: '15px' }}>
          <div style={{ backgroundColor: 'white', padding: '12px 20px', borderRadius: '8px', border: '1px solid #e2e8f0', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <span style={{ fontSize: '0.75rem', fontWeight: 700, color: '#64748b', textTransform: 'uppercase' }}>OEE Today</span>
            <span style={{ fontSize: '1.5rem', fontWeight: 900, color: '#0f172a' }}>{oeeToday}%</span>
          </div>
          <div style={{ backgroundColor: 'white', padding: '12px 20px', borderRadius: '8px', border: '1px solid #e2e8f0', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <span style={{ fontSize: '0.75rem', fontWeight: 700, color: '#64748b', textTransform: 'uppercase' }}>Active Andons</span>
            <span style={{ fontSize: '1.5rem', fontWeight: 900, color: activeAndons.length > 0 ? '#ef4444' : '#22c55e' }}>{activeAndons.length}</span>
          </div>
        </div>
      </div>

      {loading && (
        <div style={{ marginBottom: '20px', color: '#475569', fontWeight: 600 }}>Loading realtime dashboard...</div>
      )}
      {error && (
        <div style={{ marginBottom: '20px', color: '#b91c1c', fontWeight: 700 }}>{error}</div>
      )}

      {/* ACTIVE ALERTS SECTION */}
      {activeAndons.length > 0 && (
        <div style={{ marginBottom: '35px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px', marginBottom: '15px' }}>
            <div style={{ width: '12px', height: '12px', borderRadius: '50%', backgroundColor: '#ef4444', animation: 'pulse 2s infinite' }} />
            <h2 style={{ margin: 0, fontSize: '1.2rem', fontWeight: 800, color: '#ef4444', textTransform: 'uppercase', letterSpacing: '1px' }}>Action Required: Active Andon Alerts</h2>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(350px, 1fr))', gap: '20px' }}>
            {activeAndons.map(andon => (
              <div key={andon.id} style={{ backgroundColor: '#fee2e2', border: '2px solid #ef4444', borderRadius: '12px', overflow: 'hidden', boxShadow: '0 10px 15px -3px rgba(239, 68, 68, 0.2)' }}>
                <div style={{ backgroundColor: '#ef4444', padding: '12px 20px', color: 'white', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div style={{ fontWeight: 800, fontSize: '1.1rem' }}>{andon.workstation}</div>
                  <div style={{ fontSize: '1.25rem', fontWeight: 900, fontFamily: 'monospace' }}>{formatElapsed(andon.startTime)}</div>
                </div>
                <div style={{ padding: '20px' }}>
                  <div style={{ fontSize: '1.1rem', fontWeight: 700, color: '#991b1b', marginBottom: '8px' }}>{andon.category}</div>
                  {andon.detail && <p style={{ fontSize: '0.9rem', color: '#7f1d1d', margin: 0 }}>"{andon.detail}"</p>}

                  <button
                    style={{ marginTop: '20px', width: '100%', padding: '12px', backgroundColor: 'white', color: '#ef4444', border: '1px solid #ef4444', borderRadius: '6px', fontWeight: 800, cursor: 'pointer', transition: 'background-color 0.2s' }}
                    onMouseEnter={(e) => e.target.style.backgroundColor = '#fef2f2'}
                    onMouseLeave={(e) => e.target.style.backgroundColor = 'white'}
                    onClick={async () => {
                      try {
                        await acknowledgeAndon({
                          workstation: andon.workstation,
                          category: andon.category,
                          detail: andon.detail,
                          user: 'System Admin'
                        });
                        await refreshSnapshot({ silent: true });
                      } catch (err) {
                        console.error('[Home] Failed to acknowledge andon', err);
                        alert('Gagal ACK Andon. Cek koneksi Supabase.');
                      }
                    }}
                  >
                    ACKNOWLEDGE
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* WORKSTATION GRID */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
        <h2 style={{ margin: 0, fontSize: '1.25rem', fontWeight: 800, color: '#0f172a' }}>Live Stations</h2>
        <div style={{ display: 'flex', gap: '20px', fontSize: '0.8rem', color: '#64748b', fontWeight: 600 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}><div style={{ width: '8px', height: '8px', borderRadius: '50%', backgroundColor: '#2563eb' }} /> Running</div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}><div style={{ width: '8px', height: '8px', borderRadius: '50%', backgroundColor: '#94a3b8' }} /> Idle</div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}><div style={{ width: '8px', height: '8px', borderRadius: '50%', backgroundColor: '#ef4444' }} /> Down</div>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))', gap: '24px' }}>
        {workstations.map(ws => {
          const conf = getStatusColor(ws.status);
          const progress = ws.expectedOutput > 0 ? Math.round((ws.actualOutput / ws.expectedOutput) * 100) : 0;
          const isDown = ws.status === 'DOWN';
          const isRunning = ws.status === 'RUNNING';

          return (
            <div
              key={ws.id}
              style={{
                backgroundColor: 'white',
                borderRadius: '16px',
                border: `1px solid ${conf.border}`,
                boxShadow: isDown ? '0 10px 25px -5px rgba(239, 68, 68, 0.2)' : '0 4px 6px -1px rgba(0,0,0,0.05)',
                overflow: 'hidden',
                transition: 'all 0.2s',
                position: 'relative',
                display: 'flex',
                flexDirection: 'column'
              }}
            >
              {/* Status Header Bar */}
              <div style={{ height: '6px', backgroundColor: conf.accent }} />

              <div style={{ padding: '20px' }}>
                {/* Station Info Header */}
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '16px' }}>
                  <div style={{ minWidth: 0 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '4px' }}>
                       <div style={{ width: '10px', height: '10px', borderRadius: '50%', backgroundColor: ws.isOnline ? '#22c55e' : '#cbd5e1', border: '2px solid white', boxShadow: '0 0 0 1px #e2e8f0' }} />
                       <span style={{ fontSize: '0.7rem', fontWeight: 800, color: '#64748b', textTransform: 'uppercase', letterSpacing: '0.05em' }}>{ws.id}</span>
                    </div>
                    <h3 style={{ margin: 0, fontSize: '1.2rem', fontWeight: 800, color: '#0f172a', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{ws.name}</h3>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '6px', padding: '5px 12px', borderRadius: '30px', backgroundColor: conf.bg, color: conf.text, fontSize: '0.7rem', fontWeight: 800, border: `1px solid ${conf.border}` }}>
                    {conf.icon} {ws.status}
                  </div>
                </div>

                {/* Operator Info */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '12px', backgroundColor: '#f8fafc', borderRadius: '12px', marginBottom: '20px' }}>
                  <div style={{ width: '36px', height: '36px', borderRadius: '50%', backgroundColor: '#3b82f6', color: 'white', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '0.85rem', fontWeight: 900 }}>
                    {getInitials(ws.operator)}
                  </div>
                  <div style={{ minWidth: 0 }}>
                    <div style={{ fontSize: '0.65rem', fontWeight: 800, color: '#94a3b8', textTransform: 'uppercase' }}>Operator</div>
                    <div style={{ fontSize: '0.9rem', fontWeight: 700, color: '#334155', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{ws.operator}</div>
                  </div>
                </div>

                {/* App Status Section */}
                <div style={{ flex: 1 }}>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                    <div>
                      <div style={{ fontSize: '0.65rem', fontWeight: 800, color: '#94a3b8', textTransform: 'uppercase', marginBottom: '4px' }}>Active Application</div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: isRunning ? '#2563eb' : '#64748b', fontWeight: 700, fontSize: '0.95rem' }}>
                        <Zap size={16} /> {ws.activeApp}
                      </div>
                    </div>
                    {isRunning && (
                       <div>
                         <div style={{ fontSize: '0.65rem', fontWeight: 800, color: '#94a3b8', textTransform: 'uppercase', marginBottom: '4px' }}>Current Step</div>
                         <div style={{ fontSize: '0.9rem', fontWeight: 600, color: '#0f172a' }}>{ws.activeStep}</div>
                       </div>
                    )}
                  </div>
                </div>

                {/* Progress / Job Section */}
                <div style={{ marginTop: '20px', paddingTop: '16px', borderTop: '1px solid #f1f5f9' }}>
                   {ws.currentJob ? (
                     <>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '8px' }}>
                           <span style={{ fontSize: '0.75rem', fontWeight: 700, color: '#64748b' }}>Job: <span style={{ color: '#0f172a' }}>{ws.currentJob}</span></span>
                           <span style={{ fontSize: '0.85rem', fontWeight: 800, color: '#0f172a' }}>{ws.actualOutput} <span style={{ color: '#94a3b8', fontWeight: 400 }}>/ {ws.expectedOutput}</span></span>
                        </div>
                        <div style={{ height: '8px', backgroundColor: '#f1f5f9', borderRadius: '4px', overflow: 'hidden' }}>
                           <div style={{ height: '100%', width: `${progress}%`, backgroundColor: conf.accent, transition: 'width 0.8s cubic-bezier(0.4, 0, 0.2, 1)' }} />
                        </div>
                     </>
                   ) : (
                     <div style={{ fontSize: '0.8rem', color: '#94a3b8', fontStyle: 'italic', display: 'flex', alignItems: 'center', gap: '6px' }}>
                        <Clock size={14} /> Ready for next assignment
                     </div>
                   )}
                </div>
              </div>

              {/* Down Indicator Overlay */}
              {isDown && (
                <div style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, border: '3px solid #ef4444', borderRadius: '16px', pointerEvents: 'none', animation: 'pulse-border 2s infinite' }} />
              )}
            </div>
          );
        })}
      </div>

      {/* CHAT WIDGET */}
      {!showChat ? (
        <div style={{ position: 'fixed', bottom: '30px', right: '30px', zIndex: 1000 }}>
          {unreadCount > 0 && (
            <div style={{ 
              position: 'absolute', top: '-5px', right: '-5px', 
              backgroundColor: '#ef4444', color: 'white', 
              borderRadius: '50%', width: '22px', height: '22px', 
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontSize: '0.7rem', fontWeight: 900, border: '2px solid white',
              zIndex: 1001
            }}>
              {unreadCount}
            </div>
          )}
          <button 
            onClick={() => {
              setShowChat(true);
              setUnreadCount(0);
            }}
            style={{ 
              width: '60px', height: '60px', borderRadius: '50%', backgroundColor: '#001e3c', color: 'white',
              display: 'flex', alignItems: 'center', justifyContent: 'center', border: 'none',
              boxShadow: '0 10px 25px -5px rgba(0,0,0,0.3)', cursor: 'pointer', transition: 'transform 0.2s'
            }}
            onMouseEnter={e => e.currentTarget.style.transform = 'scale(1.1)'}
            onMouseLeave={e => e.currentTarget.style.transform = 'scale(1)'}
          >
            <MessageSquare size={24} />
          </button>
        </div>
      ) : (
        <ChatWidget 
          currentStation="SUPERVISOR"
          currentUser={currentUser}
          onClose={() => setShowChat(false)}
        />
      )}

    </div>
  );
};

// Global style for the pulse animation if it doesn't exist
if (typeof document !== 'undefined') {
  const style = document.createElement('style');
  style.innerHTML = `
    @keyframes pulse {
      0% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.7); }
      70% { box-shadow: 0 0 0 10px rgba(239, 68, 68, 0); }
      100% { box-shadow: 0 0 0 0 rgba(239, 68, 68, 0); }
    }
    @keyframes pulse-border {
      0% { border-color: rgba(239, 68, 68, 0.2); box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.4); }
      50% { border-color: rgba(239, 68, 68, 1); box-shadow: 0 0 20px 2px rgba(239, 68, 68, 0.6); }
      100% { border-color: rgba(239, 68, 68, 0.2); box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.4); }
    }
  `;
  document.head.appendChild(style);
}

export default Home;

src/components/InterfaceManager.jsx.content:
import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
    Monitor,
    Plus,
    Search,
    RefreshCw,
    Smartphone,
    Tablet,
    Laptop,
    Trash2,
    ExternalLink,
    XCircle,
    Info,
    ArrowRight,
    Pencil,
    CheckCircle2,
    AlertCircle
} from 'lucide-react';
import { getInterfaces, saveInterface, deleteInterface, getStations } from '../utils/database';

const InterfaceManager = () => {
    const [interfaces, setInterfaces] = useState([]);
    const [stations, setStations] = useState([]);
    const [searchTerm, setSearchTerm] = useState('');
    const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [selectedInterface, setSelectedInterface] = useState(null);
    const [newInterfaceData, setNewInterfaceData] = useState({ name: '', deviceType: 'Computer', stationId: '' });
    const [editInterfaceData, setEditInterfaceData] = useState({ id: '', name: '', stationId: '' });
    const [isSaving, setIsSaving] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        const [i, s] = await Promise.all([getInterfaces(), getStations()]);
        setInterfaces(i);
        setStations(s);
    };

    const getDeviceIcon = (type) => {
        switch (type) {
            case 'Phone': return <Smartphone size={20} />;
            case 'Tablet': return <Tablet size={20} />;
            default: return <Laptop size={20} />;
        }
    };

    const deriveConnectionState = (iface) => {
        if (!iface?.lastSeen) return 'OFFLINE';
        const ageMs = Date.now() - new Date(iface.lastSeen).getTime();
        return ageMs <= 5 * 60 * 1000 ? 'ONLINE' : 'OFFLINE';
    };

    const getConnectionBadge = (state) => {
        if (state === 'ONLINE') {
            return {
                color: '#10b981',
                bg: '#dcfce7',
                icon: <CheckCircle2 size={12} />
            };
        }
        return {
            color: '#b45309',
            bg: '#fef3c7',
            icon: <AlertCircle size={12} />
        };
    };

    const handleLaunchPlayer = (iface) => {
        const station = stations.find(s => s.id === iface.stationId);
        const stationName = station ? station.name : 'WS-01';
        // Open in new tab for player experience
        window.open(`/terminal?station=${encodeURIComponent(stationName)}`, '_blank');
    };

    const filteredInterfaces = useMemo(() => {
        return interfaces.filter((i) =>
            i.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
            (i.ipAddress || '').toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [interfaces, searchTerm]);

    const handleCreateInterface = async () => {
        if (!newInterfaceData.name.trim()) {
            alert('Interface Name is required.');
            return;
        }

        setIsSaving(true);
        try {
            const iface = {
                ...newInterfaceData,
                status: 'ONLINE',
                version: 'r284.1',
                lastSeen: new Date().toISOString(),
                ipAddress: `192.168.1.${Math.floor(Math.random() * 254 + 1)}`
            };
            await saveInterface(iface);
            setIsCreateModalOpen(false);
            setNewInterfaceData({ name: '', deviceType: 'Computer', stationId: '' });
            await loadData();
        } catch (err) {
            console.error('Failed to register interface:', err);
            alert(`Failed to register interface: ${err.message || 'Unknown error'}. Please check your database connection.`);
        } finally {
            setIsSaving(false);
        }
    };

    const handleOpenEdit = (iface) => {
        setSelectedInterface(iface);
        setEditInterfaceData({
            id: iface.id,
            name: iface.name || '',
            stationId: iface.stationId || ''
        });
        setIsEditModalOpen(true);
    };

    const handleSaveEdit = async () => {
        if (!selectedInterface) return;
        if (!editInterfaceData.name.trim()) {
            alert('Interface Name is required.');
            return;
        }

        setIsSaving(true);
        try {
            await saveInterface({
                ...selectedInterface,
                name: editInterfaceData.name.trim(),
                stationId: editInterfaceData.stationId,
                lastSeen: selectedInterface.lastSeen || new Date().toISOString()
            });
            setIsEditModalOpen(false);
            setSelectedInterface(null);
            await loadData();
        } catch (err) {
            console.error('Failed to update interface:', err);
            alert(`Failed to update interface: ${err.message || 'Unknown error'}`);
        } finally {
            setIsSaving(false);
        }
    };

    const handleDeleteInterface = async (id) => {
        if (window.confirm('Are you sure you want to remove this interface?')) {
            await deleteInterface(id);
            if (selectedInterface?.id === id) setSelectedInterface(null);
            await loadData();
        }
    };

    return (
        <div style={{ height: '100%', display: 'flex', flexDirection: 'column', backgroundColor: '#f8fafc' }}>
            <div style={{ padding: '24px', borderBottom: '1px solid #e2e8f0', backgroundColor: 'white', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                    <h2 style={{ margin: 0, fontSize: '1.5rem', fontWeight: 900, color: '#0f172a' }}>Interfaces (Display Devices)</h2>
                    <p style={{ margin: '4px 0 0 0', color: '#64748b', fontSize: '0.9rem' }}>Monitor and manage display devices running the MES Player</p>
                </div>
                <div style={{ display: 'flex', gap: '12px' }}>
                    <button onClick={loadData} style={{ padding: '10px', borderRadius: '8px', border: '1px solid #e2e8f0', backgroundColor: 'white', cursor: 'pointer' }}>
                        <RefreshCw size={18} color="#64748b" />
                    </button>
                    <button onClick={() => setIsCreateModalOpen(true)} style={{ display: 'flex', alignItems: 'center', gap: '8px', padding: '10px 20px', backgroundColor: '#3b82f6', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 700, cursor: 'pointer' }}>
                        <Plus size={18} /> Create Interface
                    </button>
                </div>
            </div>

            <div style={{ padding: '24px' }}>
                <div style={{ position: 'relative', maxWidth: '420px', marginBottom: '24px' }}>
                    <Search style={{ position: 'absolute', left: '12px', top: '50%', transform: 'translateY(-50%)', color: '#94a3b8' }} size={16} />
                    <input type="text" placeholder="Search by name or IP address..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} style={{ width: '100%', padding: '12px 12px 12px 40px', borderRadius: '10px', border: '1px solid #e2e8f0', backgroundColor: 'white' }} />
                </div>

                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(330px, 1fr))', gap: '20px' }}>
                    {filteredInterfaces.map((iface) => {
                        const station = stations.find((s) => s.id === iface.stationId);
                        const connectionState = deriveConnectionState(iface);
                        const badge = getConnectionBadge(connectionState);

                        return (
                            <div key={iface.id} style={{ backgroundColor: 'white', borderRadius: '16px', border: '1px solid #e2e8f0', overflow: 'hidden', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.05)' }}>
                                <div style={{ padding: '20px', borderBottom: '1px solid #f1f5f9', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                                        <div style={{ width: '40px', height: '40px', borderRadius: '10px', backgroundColor: '#f1f5f9', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#3b82f6' }}>
                                            {getDeviceIcon(iface.deviceType)}
                                        </div>
                                        <div>
                                            <div style={{ fontWeight: 800, color: '#1e293b' }}>{iface.name}</div>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '6px', fontSize: '0.7rem', fontWeight: 700, color: badge.color, backgroundColor: badge.bg, borderRadius: '20px', width: 'fit-content', padding: '3px 8px', marginTop: '4px' }}>
                                                {badge.icon} {connectionState}
                                            </div>
                                        </div>
                                    </div>
                                    <div style={{ display: 'flex', gap: '8px' }}>
                                        <button onClick={() => handleOpenEdit(iface)} style={{ border: '1px solid #e2e8f0', background: 'white', cursor: 'pointer', color: '#3b82f6', borderRadius: '6px', width: '30px', height: '30px', display: 'inline-flex', alignItems: 'center', justifyContent: 'center' }}>
                                            <Pencil size={14} />
                                        </button>
                                        <button onClick={() => handleDeleteInterface(iface.id)} style={{ border: '1px solid #fee2e2', background: 'white', cursor: 'pointer', color: '#ef4444', borderRadius: '6px', width: '30px', height: '30px', display: 'inline-flex', alignItems: 'center', justifyContent: 'center' }}>
                                            <Trash2 size={14} />
                                        </button>
                                    </div>
                                </div>

                                <div style={{ padding: '20px' }}>
                                    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem' }}>
                                            <span style={{ color: '#64748b' }}>Assigned Station</span>
                                            <span style={{ fontWeight: 700, color: '#3b82f6', display: 'flex', alignItems: 'center', gap: '4px' }}>
                                                {station ? station.name : 'Unassigned'} <ArrowRight size={12} />
                                            </span>
                                        </div>
                                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem' }}>
                                            <span style={{ color: '#64748b' }}>Software Version</span>
                                            <span style={{ fontWeight: 600 }}>{iface.version || 'r284.1'}</span>
                                        </div>
                                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem' }}>
                                            <span style={{ color: '#64748b' }}>IP Address</span>
                                            <span style={{ fontWeight: 600 }}>{iface.ipAddress || '-'}</span>
                                        </div>
                                        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem' }}>
                                            <span style={{ color: '#64748b' }}>Last Seen</span>
                                            <span style={{ fontWeight: 600 }}>{iface.lastSeen ? new Date(iface.lastSeen).toLocaleString() : '-'}</span>
                                        </div>
                                    </div>
                                    <button 
                                        onClick={() => handleLaunchPlayer(iface)}
                                        style={{ width: '100%', marginTop: '20px', padding: '10px', backgroundColor: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '8px', fontWeight: 700, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px' }}
                                        onMouseEnter={(e) => e.target.style.backgroundColor = '#f1f5f9'}
                                        onMouseLeave={(e) => e.target.style.backgroundColor = '#f8fafc'}
                                    >
                                        Launch Player <ExternalLink size={14} />
                                    </button>
                                </div>
                            </div>
                        );
                    })}
                </div>

                {filteredInterfaces.length === 0 && (
                    <div style={{ textAlign: 'center', padding: '80px', backgroundColor: 'white', borderRadius: '16px', border: '1px dashed #cbd5e1' }}>
                        <Monitor size={48} color="#cbd5e1" style={{ marginBottom: '16px' }} />
                        <h3 style={{ margin: 0, color: '#1e293b' }}>No interfaces registered</h3>
                        <p style={{ color: '#64748b', maxWidth: '340px', margin: '8px auto' }}>Create your first display interface to start running apps on the shop floor.</p>
                        <button onClick={() => setIsCreateModalOpen(true)} style={{ marginTop: '16px', padding: '10px 24px', backgroundColor: '#3b82f6', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 700, cursor: 'pointer' }}>
                            Get Started
                        </button>
                    </div>
                )}
            </div>

            {isCreateModalOpen && (
                <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 2000 }}>
                    <div style={{ backgroundColor: 'white', width: '500px', borderRadius: '16px', overflow: 'hidden' }}>
                        <div style={{ padding: '24px', borderBottom: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <h2 style={{ margin: 0, fontSize: '1.25rem', fontWeight: 800 }}>Create Interface</h2>
                            <button onClick={() => setIsCreateModalOpen(false)} style={{ border: 'none', background: 'none', cursor: 'pointer' }}><XCircle size={20} color="#94a3b8" /></button>
                        </div>
                        <div style={{ padding: '24px', display: 'flex', flexDirection: 'column', gap: '20px' }}>
                            <div style={{ padding: '16px', backgroundColor: '#f0f9ff', borderRadius: '12px', border: '1px solid #bae6fd', display: 'flex', gap: '12px' }}>
                                <Info size={20} color="#0284c7" />
                                <div style={{ fontSize: '0.85rem', color: '#0369a1' }}>Interfaces are display devices (tablets, PCs, phones) running the Player. Assign each interface to a station.</div>
                            </div>
                            <div>
                                <label style={{ fontSize: '0.75rem', fontWeight: 800, color: '#64748b', textTransform: 'uppercase', marginBottom: '8px', display: 'block' }}>Interface Name</label>
                                <input type="text" style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #e2e8f0' }} placeholder="e.g. Line 1 Tablet" value={newInterfaceData.name} onChange={(e) => setNewInterfaceData({ ...newInterfaceData, name: e.target.value })} />
                            </div>
                            <div>
                                <label style={{ fontSize: '0.75rem', fontWeight: 800, color: '#64748b', textTransform: 'uppercase', marginBottom: '8px', display: 'block' }}>Device Type</label>
                                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '12px' }}>
                                    {['Computer', 'Tablet', 'Phone'].map((type) => (
                                        <button key={type} onClick={() => setNewInterfaceData({ ...newInterfaceData, deviceType: type })} style={{ padding: '12px', borderRadius: '8px', border: '1px solid #e2e8f0', backgroundColor: newInterfaceData.deviceType === type ? '#eff6ff' : 'white', borderColor: newInterfaceData.deviceType === type ? '#3b82f6' : '#e2e8f0', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px', cursor: 'pointer', fontWeight: 700 }}>
                                            {getDeviceIcon(type)}
                                            <span style={{ fontSize: '0.75rem' }}>{type}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <div>
                                <label style={{ fontSize: '0.75rem', fontWeight: 800, color: '#64748b', textTransform: 'uppercase', marginBottom: '8px', display: 'block' }}>Initial Station Assignment</label>
                                <select style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #e2e8f0', backgroundColor: 'white' }} value={newInterfaceData.stationId} onChange={(e) => setNewInterfaceData({ ...newInterfaceData, stationId: e.target.value })}>
                                    <option value="">Unassigned</option>
                                    {stations.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
                                </select>
                            </div>
                        </div>
                        <div style={{ padding: '24px', backgroundColor: '#f8fafc', borderTop: '1px solid #e2e8f0', display: 'flex', justifyContent: 'flex-end', gap: '12px' }}>
                            <button onClick={() => setIsCreateModalOpen(false)} style={{ padding: '10px 20px', borderRadius: '8px', border: '1px solid #e2e8f0', backgroundColor: 'white', fontWeight: 700, cursor: 'pointer' }}>Cancel</button>
                            <button onClick={handleCreateInterface} disabled={isSaving} style={{ padding: '10px 24px', borderRadius: '8px', backgroundColor: isSaving ? '#94a3b8' : '#3b82f6', color: 'white', border: 'none', fontWeight: 700, cursor: isSaving ? 'not-allowed' : 'pointer' }}>{isSaving ? 'Creating...' : 'Create Interface'}</button>
                        </div>
                    </div>
                </div>
            )}

            {isEditModalOpen && (
                <div style={{ position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 2100 }}>
                    <div style={{ backgroundColor: 'white', width: '500px', borderRadius: '16px', overflow: 'hidden' }}>
                        <div style={{ padding: '24px', borderBottom: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <h2 style={{ margin: 0, fontSize: '1.25rem', fontWeight: 800 }}>Edit Interface</h2>
                            <button onClick={() => setIsEditModalOpen(false)} style={{ border: 'none', background: 'none', cursor: 'pointer' }}><XCircle size={20} color="#94a3b8" /></button>
                        </div>
                        <div style={{ padding: '24px', display: 'flex', flexDirection: 'column', gap: '20px' }}>
                            <div>
                                <label style={{ fontSize: '0.75rem', fontWeight: 800, color: '#64748b', textTransform: 'uppercase', marginBottom: '8px', display: 'block' }}>Interface Name</label>
                                <input type="text" style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #e2e8f0' }} value={editInterfaceData.name} onChange={(e) => setEditInterfaceData({ ...editInterfaceData, name: e.target.value })} />
                            </div>
                            <div>
                                <label style={{ fontSize: '0.75rem', fontWeight: 800, color: '#64748b', textTransform: 'uppercase', marginBottom: '8px', display: 'block' }}>Assigned Station</label>
                                <select style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #e2e8f0', backgroundColor: 'white' }} value={editInterfaceData.stationId} onChange={(e) => setEditInterfaceData({ ...editInterfaceData, stationId: e.target.value })}>
                                    <option value="">Unassigned</option>
                                    {stations.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
                                </select>
                            </div>
                        </div>
                        <div style={{ padding: '24px', backgroundColor: '#f8fafc', borderTop: '1px solid #e2e8f0', display: 'flex', justifyContent: 'flex-end', gap: '12px' }}>
                            <button onClick={() => setIsEditModalOpen(false)} style={{ padding: '10px 20px', borderRadius: '8px', border: '1px solid #e2e8f0', backgroundColor: 'white', fontWeight: 700, cursor: 'pointer' }}>Cancel</button>
                            <button onClick={handleSaveEdit} disabled={isSaving} style={{ padding: '10px 24px', borderRadius: '8px', backgroundColor: isSaving ? '#94a3b8' : '#3b82f6', color: 'white', border: 'none', fontWeight: 700, cursor: isSaving ? 'not-allowed' : 'pointer' }}>{isSaving ? 'Saving...' : 'Save Changes'}</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default InterfaceManager;

