          } else if (comp.type === 'DROPDOWN') {
            setDropdownValues(prev => prev[comp.id] === val ? prev : { ...prev, [comp.id]: val });
          } else if (comp.type === 'RADIO_GROUP') {
            setRadioValues(prev => prev[comp.id] === val ? prev : { ...prev, [comp.id]: val });
