            >
              Next Step
            </button>
          )}
        </div>

        {/* DEFECT/ANDON Modals will render here via standard portals/overlays */}
      </div>
    );
  }

  return (
    <div style={{
      height: '100%',
      backgroundColor: '#f1f5f9',
      color: '#0f172a',
      display: 'flex',
      flexDirection: 'column',
