                    </div>
                    <div style={{ fontSize: '0.65rem', color: '#94a3b8', fontWeight: 600 }}>
                      {appComponents.length} Widgets
                    </div>
                  </div>
                </div>

                {showWorkSequence && (
                  <div style={{ display: 'flex', gap: '10px', overflowX: 'auto', paddingBottom: '10px', animation: 'fadeIn 0.3s ease-in-out' }}>
