                                                            <th style={{ padding: tableDensity === 'compact' ? '10px' : '16px', textAlign: 'left', fontSize: '0.75rem', fontWeight: 700, color: TOKENS.textMuted, textTransform: 'uppercase' }}>Actions</th>
                                                        </tr>
                                                    </thead>
                                                    <tbody>
                                                        {filteredAndSortedRecords.map((record, idx) => (
                                                            <tr
                                                                key={record.id}
