                                                                    style={{ padding: '4px 8px', borderRadius: '999px', backgroundColor: '#eef2ff', border: '1px solid #c7d2fe', color: '#3730a3', fontSize: '0.7rem', fontWeight: 700, cursor: 'grab' }}
