                                                                {zone.key === 'values' && (editingQuery?.pivot?.values || []).map((f) => <span key={`v-${f.key}`} style={{ padding: '3px 8px', borderRadius: '999px', backgroundColor: '#f3e8ff', color: '#6b21a8', fontSize: '0.7rem', fontWeight: 700 }}>{f.key}:{f.aggregation}</span>)}
