                                                onMouseEnter={e => e.currentTarget.style.backgroundColor = '#fff1f2'}
                                                onMouseLeave={e => e.currentTarget.style.backgroundColor = 'transparent'}
                                            ><Trash2 size={18} /></button>
                                        </div>
                                    ))}
                                </div>
                            </div>
