}

/* Mavi Panel Classes */
.mavi-panel {
  background: white;
  border: 1px solid var(--bg-tertiary);
  border-radius: 8px;
  box-shadow: 0 1px 2px rgba(0,0,0,0.05);
}

.mavi-card {
  background: white;
