                x: 820, y: 10, w: 120, h: 40,
                props: { text: 'Back', backgroundColor: '#64748b', color: 'white' },
                triggers: [
                    { event: 'ON_CLICK', type: 'NAVIGATION', action: 'GO_TO_STEP', stepId: `s_station_${ts}` }
                ]
            },

            // Open Alerts Table
            {
                id: `c17_${ts}`, type: 'INTERACTIVE_TABLE',
                x: 20, y: 70, w: 440, h: 400,
