                    tableId: T.actions,
                    title: 'Open Alerts',
                    columns: ['Location', 'Title', 'Work_Order_ID', 'Severity'],
                    linkedRecordPlaceholderId: `r2_${ts}`,
                    variableFilters: [
                        { variableName: 'Selected_Station_ID', columnName: 'Location' }
