        { id: `v1_${ts}`, name: 'CycleTime_KPI', type: 'string', defaultValue: '25:20:15', persisted: true },
        { id: `v2_${ts}`, name: 'Pending_Kanbans_Count', type: 'number', defaultValue: 3, persisted: true },
