            {
                id: `kpi_cyc_val_${ts}`, type: 'TEXT',
                x: 580, y: 55, w: 170, h: 100,
                props: { text: '{{@CycleTime_KPI}}', fontSize: 32, fontWeight: 'bold', color: '#0f172a' }
