            },
            {
                id: `cf_btn_save_${ts}`, type: 'BUTTON',
                x: 480, y: 320, w: 200, h: 50,
                props: { text: '✓ Create request', backgroundColor: '#16a34a', color: 'white', fontWeight: 'bold' },
